    static final long MOD = 998244353L;

    static long modPow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) != 0) {
                result = result * base % MOD;
            }
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int k = fs.nextInt();
        long l = fs.nextLong();

        int max = 2 * n + 1;
        long[] fact = new long[max + 1];
        long[] invFact = new long[max + 1];
        long[] inv = new long[n + 1];

        fact[0] = 1;
        for (int i = 1; i <= max; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }

        invFact[max] = modPow(fact[max], MOD - 2);
        for (int i = max; i >= 1; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        inv[1] = 1;
        for (int i = 2; i <= n; i++) {
            inv[i] = (MOD - (MOD / i) * inv[(int) (MOD % i)] % MOD) % MOD;
        }

        long choose = fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
        long powerOfTwo = modPow(2, k);
        long total = 0;

        for (int j = k; j <= n; j++) {
            int m = n - j;
            long innerSum = 0;
            long comb = 1;

            for (int t = 0; t <= m; t++) {
                int a = j + 2 * t;
                int b = j + 2 * (m - t);

                long term = comb * fact[a] % MOD * fact[b] % MOD;
                innerSum += term;
                if (innerSum >= MOD) innerSum -= MOD;

                if (t < m) {
                    comb = comb * (m - t) % MOD * inv[t + 1] % MOD;
                }
            }

            long contribution = choose * powerOfTwo % MOD * innerSum % MOD;
            total += contribution;
            if (total >= MOD) total -= MOD;

            if (j < n) {
                choose = choose * (n - j) % MOD * inv[j + 1] % MOD;
                powerOfTwo = powerOfTwo * 2 % MOD;
            }
        }

        long answer = total * invFact[2 * n + 1] % MOD;
        answer = answer * (l % MOD) % MOD;

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
